// STS mission demo (simulated model)
var legs=['LEO','transfer','arrival'];
for(var i=0;i<legs.length;i++){console.log('leg '+(i+1)+': '+legs[i]);}
console.log('STS designed '+legs.length+' legs');

// SigProp demo (simulated model)
var r=7000;
for(var i=0;i<4;i++){var dt=r<10000?60:600;r+=8000;console.log('r='+r+' dt='+dt);}
console.log('SigProp adaptive steps done');

// SigForces demo (simulated model)
var f=[['grav',8.7],['drag',0.0002],['SRP',0.00005]], tot=0;
for(var i=0;i<f.length;i++){tot+=f[i][1];console.log(f[i][0]+' '+f[i][1]);}
console.log('SigForces total '+tot.toFixed(4)+' m/s^2');

// Signature burn demo (simulated model)
var dv=2.5, m0=1500, isp=320;
var mp=m0*(1-Math.exp(-dv*1000/(isp*9.80665)));
console.log('dv='+dv+'km/s needs '+mp.toFixed(1)+'kg propellant');
console.log('Signature finite-burn math');

// SigTarget demo (simulated model)
var miss=800;
for(var i=0;i<4;i++){miss*=0.12;console.log('iter '+i+' miss='+miss.toFixed(1)+'km');}
console.log('SigTarget converged');

// SigEst demo (simulated model)
var m=[5005,4992,5001,4998], s=0;
for(var i=0;i<m.length;i++){s+=m[i];}
console.log('SigEst fit: '+(s/m.length).toFixed(1)+' over '+m.length+' points');

// SigScript demo (simulated model)
var s=['create craft c','create prop p','propagate p(c) 2 days','achieve alt 400km'];
for(var i=0;i<s.length;i++){console.log('> '+s[i]);}
console.log('SigScript: '+s.length+' lines');

// Signature frame demo (simulated model)
var a=45*Math.PI/180;
console.log('rotated x='+(Math.cos(a)).toFixed(3)+' y='+(Math.sin(a)).toFixed(3));
console.log('Signature frame math');

// SigOpt demo (simulated model)
var best=1e9, bx=0;
for(var x=0;x<10;x++){var v=(x-4)*(x-4)+1;if(v<best){best=v;bx=x;}}
console.log('SigOpt: x='+bx+' cost='+best.toFixed(1));

// Lunar profile demo (simulated model)
var ph=['TLI','LOI','orbit','keep'];
for(var i=0;i<ph.length;i++){console.log('phase '+(i+1)+': '+ph[i]);}
console.log('lunar profile closed');

// Asteroid profile demo (simulated model)
var r=5000;
for(var i=0;i<3;i++){r/=4;console.log('range '+r+'m');}
console.log('Signature proximity held');

// Resonance demo (simulated model)
console.log('resonance 2:1 period ratio '+(27.3/13.6).toFixed(2));
console.log('Signature resonant design');

// STS validation demo (simulated model)
var err=0.4;
console.log('STS error vs truth: '+err+'%');
console.log(err<1?'VALIDATED':'FAILED');

// Ephemeris demo (simulated model)
var b=['Earth','Moon'], p=[[0,0],[384400,0]];
for(var i=0;i<b.length;i++){console.log(b[i]+' '+p[i][0]+'km');}
console.log('Signature ephemeris consistent');

// Signature loop demo (simulated model)
var l=['sketch','script','propagate','target','optimize','estimate','validate','fly'];
for(var i=0;i<l.length;i++){console.log((i+1)+'. '+l[i]);}
console.log('Signature loop closed');
